extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var q1 := Question.new("Q1", ["A", "B"], 0)
	var session_correct := QuizSession.new([q1])
	session_correct.submit_answer(0)
	check("correct_score", session_correct.score == 1, "Una risposta corretta deve impostare lo score a 1 (trovato score = %d)" % session_correct.score)
	var q2 := Question.new("Q2", ["A", "B"], 0)
	var session_wrong := QuizSession.new([q2])
	session_wrong.submit_answer(1)
	check("wrong_score", session_wrong.score == 0, "Una risposta errata deve lasciare lo score a 0 (trovato score = %d)" % session_wrong.score)

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var quiz_data = get_node_or_null("/root/QuizData")
	if quiz_data == null:
		quiz_data = instantiate_script("res://quiz_data.gd")
	if not check("quiz_data", quiz_data != null, "Lo script res://quiz_data.gd deve poter essere istanziato"):
		return
	quiz_data.topic_records = {"Videogiochi": 85, "Cinema": 40}
	quiz_data.save_topic_records()
	quiz_data.topic_records = {}
	var loaded = quiz_data.load_topic_records()
	check("file_loaded", bool(loaded), "load_topic_records() deve restituire true dopo il salvataggio")
	var rec = quiz_data.get_topic_record("Videogiochi")
	check("data_saved", int(rec) == 85, "Il record salvato per Videogiochi deve essere 85 (trovato %s)" % str(rec))

